Lemma sc_pro : forall (Q : machine_state -> Prop) (S ioc regb cfgb lo shi : Z) (LB : list block) (LF : list fframe)
    (ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (errv : word) (junk : list byte),
  rw_cells asegs m S [CB 272 junk] -> addressable m S NEWSZ_SCH -> shvis m S (S + NEWSZ_SCH) ->
  asc_pure H S ioc regb cfgb lo shi sp tp ra -> asc_fs H LF S ioc regb cfgb -> asc_inv LB m ioc regb cfgb errv ->
  stk asegs m lo (bv_unsigned sp) -> mem_inv asegs m ->
  ACONST m -> athr_cells m -> as_RFS H LF m -> (length LF + 1 < AFS_MAXLIVE)%nat -> stack0 m lo shi ->
  (forall (m2 : mem) (spa : Z) (gap : list cell) (p56 p16 h32 j472 shb : list byte) (ff fp : Z)
          (rax a0' a1' a2' a3' a4' a5' a6' a7' t0' t1' t2' t3' t4' t5' t6' : word),
     rw_cells asegs m2 spa [CB 56 p56; C8 (Z_to_bv 64 ff); CB 16 p16] ->
     rw_cells asegs m2 (spa + 80) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 80) ->
     (spa = bv_unsigned sp + -192 \/ spa = bv_unsigned sp + -208) ->
     rw_cells asegs m2 (bv_unsigned sp + -104) (sc_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
     rw_cells asegs m2 ff [CB 32 h32; CB 472 j472; C8 (Z_to_bv 64 fp)] ->
     rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880) [CB 64 shb] ->
     rw_cells asegs m2 fp [C1 (b8 1)] ->
     stk asegs m2 lo spa -> mem_inv asegs m2 ->
     as_RFS H ((3, ff, fp) :: LF) m2 -> fresh_frame H LF 3 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
     munch ([(lo, bv_unsigned sp)]%Z ++ fr3_XS H ff fp) m m2 -> wmono asegs m m2 ->
     rw_cells asegs m2 S [CB 272 junk] -> addressable m2 S NEWSZ_SCH -> shvis m2 S (S + NEWSZ_SCH) -> asc_inv LB m2 ioc regb cfgb errv ->
     evt asegs Q
       (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
                (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 S) s5 (Z_to_bv 64 0) (Z_to_bv 64 P_A_SCHED_GET_DEFAULT_TASK)
                (Z_to_bv 64 ioc) s9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3' t4' t5' t6')
           F (Z_to_bv 64 P_A_SC_U1) fc None m2 (seg_rom asegs))) ->
  evt asegs Q
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz S) (wz ioc) (wz 0) (wz P_A_SCHED_GET_DEFAULT_TASK) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SCHED_CTOR) fc None m (seg_rom asegs)).
